import { useEffect } from "react";
import { MapContainer, TileLayer, useMap } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import AlbumBubble from "./AlbumBubble.jsx";

function MapController({ location }) {
  const map = useMap();
  useEffect(() => {
    if (location) {
      map.flyTo([location.lat, location.lng], 6, { duration: 1.5 });
    }
  }, [location, map]);
  return null;
}

export default function LeafletMap({ track, location }) {
  return (
    <MapContainer
      center={[20, 0]}
      zoom={2}
      style={{ height: "100vh", width: "100%" }}
    >
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      />
      {location && track && (
        <>
          <MapController location={location} />
          <AlbumBubble
            location={location}
            imageUrl={track.albumImageUrl}
            trackName={track.trackName}
            artistName={track.artistName}
          />
        </>
      )}
    </MapContainer>
  );
}

import L from "leaflet";
import { useMemo } from "react";
import { Marker, Popup } from "react-leaflet";
import "./albumPopup.css";
import AlbumPopupCard from "./AlbumPopupCard.jsx";

export default function AlbumBubble({
  location,
  imageUrl,
  trackName,
  artistName,
}) {
  const icon = useMemo(() => {
    const img = document.createElement("img");
    img.src = imageUrl ?? "";
    img.alt = artistName;
    img.style.cssText =
      "width:64px;height:64px;border-radius:50%;border:3px solid white;box-shadow:0 2px 12px rgba(0,0,0,0.5);display:block;";
    return L.divIcon({
      html: img,
      className: "",
      iconSize: [64, 64],
      iconAnchor: [32, 32],
      popupAnchor: [0, -36],
    });
  }, [imageUrl, artistName]);

  // Use == null (not truthiness) so a valid 0 coordinate — e.g. the Pacific
  // "Unknown location" fallback at lat 0 — still renders the bubble.
  if (location?.lat == null || location?.lng == null) return null;

  return (
    <Marker position={[location.lat, location.lng]} icon={icon}>
      <Popup>
        <AlbumPopupCard
          imageUrl={imageUrl}
          trackName={trackName}
          artistName={artistName}
          placeName={location.placeName}
        />
      </Popup>
    </Marker>
  );
}
