import { beforeEach, describe, expect, it } from "vitest";
import { applyFavicon, FAVICON_DEV, FAVICON_PROD, faviconHref } from "../favicon.js";

describe("faviconHref", () => {
  it("returns the dev icon when running locally", () => {
    expect(faviconHref(true)).toBe(FAVICON_DEV);
  });

  it("returns the production icon otherwise", () => {
    expect(faviconHref(false)).toBe(FAVICON_PROD);
  });

  it("uses two distinct files so the tabs cannot be confused", () => {
    expect(FAVICON_DEV).not.toBe(FAVICON_PROD);
  });
});

describe("applyFavicon", () => {
  beforeEach(() => {
    document.head.innerHTML = "";
  });

  it("creates the icon link when the document has none", () => {
    const link = applyFavicon(document, true);

    expect(document.head.querySelectorAll("link[rel='icon']")).toHaveLength(1);
    expect(link.getAttribute("href")).toBe(FAVICON_DEV);
    expect(link.getAttribute("type")).toBe("image/svg+xml");
  });

  it("reuses the link already declared in index.html rather than adding a second", () => {
    const existing = document.createElement("link");
    existing.rel = "icon";
    existing.href = FAVICON_PROD;
    document.head.appendChild(existing);

    const link = applyFavicon(document, true);

    expect(link).toBe(existing);
    expect(document.head.querySelectorAll("link[rel='icon']")).toHaveLength(1);
    expect(link.getAttribute("href")).toBe(FAVICON_DEV);
  });

  it("leaves the production icon in place outside dev", () => {
    const link = applyFavicon(document, false);
    expect(link.getAttribute("href")).toBe(FAVICON_PROD);
  });
});

// Local and deployed tabs must be tellable apart at a glance. Both icons draw
// the same globe; the dev one shifts hue and inverts its linework so the
// difference survives a 16px favicon and colour-vision deficiency.
export const FAVICON_PROD = "/favicon.svg";
export const FAVICON_DEV = "/favicon-dev.svg";

export function faviconHref(isDev) {
  return isDev ? FAVICON_DEV : FAVICON_PROD;
}

// index.html already ships the production icon, so the tab is never blank
// before this runs. Reuse that link when present rather than appending a
// second one, which would leave the browser to pick between them.
export function applyFavicon(doc, isDev) {
  let link = doc.querySelector("link[rel='icon']");
  if (!link) {
    link = doc.createElement("link");
    link.setAttribute("rel", "icon");
    doc.head.appendChild(link);
  }
  link.setAttribute("type", "image/svg+xml");
  link.setAttribute("href", faviconHref(isDev));
  return link;
}

